  description_long = $dl22u$Recraft відрізняється від інших генераторів зображень фокусом на професійному графічному дизайні. Дозволяє генерувати зображення у форматі SVG (векторний), що є унікальним на ринку. Функція Brand Kit дозволяє визначати кольори, стилі та візуальні елементи для послідовних генерацій. Ідеально для UX/UI-дизайнерів, маркетингових команд і контент-мейкерів.$dl22u$,
  pros = ARRAY['Підтримка SVG та векторних форматів', 'Brand Kit для візуальної послідовності', 'Іконки та UI-елементи', 'Висока якість у графічному дизайні'],
  cons = ARRAY['Менш універсальний для концептуального мистецтва', 'Менш інтуїтивний інтерфейс для початківців', 'Обмежені кредити в безкоштовному тарифі']
WHERE slug = 'recraft-ai' AND lang = 'ua';

UPDATE tools SET
