  description_long = $dl23u$Ideogram вирішив одну з найбільших проблем генерації зображень з AI: нечитабельний текст. Модель генерує текст, ідеально інтегрований у зображення, з різними шрифтами та правильним правописом. Ideogram 2.0 додає також контроль кольорової палітри та генерацію патернів. Улюблений інструмент для маркетингових матеріалів, обкладинок, постерів та будь-яких зображень, що потребують видимого тексту.$dl23u$,
  pros = ARRAY['Читабельний і добре оформлений текст у зображеннях', 'Контроль кольорової палітри', 'Ідеально для маркетингових матеріалів', 'Дуже простий у використанні інтерфейс'],
  cons = ARRAY['Слабший у складних фотореалістичних зображеннях', 'Менше стильових опцій ніж у Midjourney', 'Щоденні ліміти в безкоштовному тарифі']
WHERE slug = 'ideogram' AND lang = 'ua';

UPDATE tools SET
