  description_long = $dl26u$Luma AI відома двома основними продуктами: Dream Machine (генерація відео з AI) та Luma 3D (захоплення 3D-сцен з відео). Dream Machine виробляє відео з плавними рухами та фотореалістичною якістю, особливо сильний у сценах з водою, димом та іншими складними фізичними ефектами. Функція 3D дозволяє дизайнерам і розробникам захоплювати реальні обʼєкти та перетворювати їх на 3D-моделі.$dl26u$,
  pros = ARRAY['Фотореалістичні відео високої якості', '3D-захоплення та реконструкція', 'Відмінний у складних фізичних ефектах', 'API доступний для розробників'],
  cons = ARRAY['Повільний час генерації', 'Обмежені безкоштовні кредити', 'Функція 3D потребує гарних умов зйомки']
WHERE slug = 'luma-ai' AND lang = 'ua';

