  description_long = $dl29u$Canva інтегрувала повний набір AI-інструментів: Magic Design (генерує повні дизайни з опису), Magic Write (написання текстів з AI), Magic Eraser (видалення обʼєктів із зображень), Text to Image та інші. Зі 150+ мільйонами користувачів Canva AI демократизує графічний дизайн для маркетингових команд, педагогів, підприємців і контент-мейкерів без технічних знань дизайну.$dl29u$,
  pros = ARRAY['Бездоганна інтеграція в платформу Canva', 'Дуже простий у використанні', 'Повний набір AI-інструментів', '150М+ користувачів і величезна бібліотека шаблонів'],
  cons = ARRAY['Якість зображень нижча ніж у Midjourney та FLUX', 'AI-функції потребують платного тарифу', 'Менший творчий контроль для досвідчених дизайнерів']
WHERE slug = 'canva-ai' AND lang = 'ua';

UPDATE tools SET
