  description      = $d30u$Krea AI — платформа генерації зображень з AI, що вирізняється генерацією в реальному часі та новою моделлю Krea 2 з винятковою якістю зображень.$d30u$,
  description_long = $dl30u$Krea AI пропонує унікальний досвід генерації зображень: модель генерує та оновлює зображення в реальному часі, поки користувач друкує або малює, дозволяючи ультрашвидку ітерацію. З запуском Krea 2 у травні 2026 якість зображень зробила значний стрибок, конкуруючи безпосередньо з FLUX і Midjourney. Включає інструменти апскейлінгу, покращення зображень та генерації патернів.$dl30u$,
  pros = ARRAY['Генерація в реальному часі', 'Krea 2 з винятковою якістю', 'Апскейлінг і покращення зображень', 'Ідеально для швидкої творчої ітерації'],
  cons = ARRAY['Менше опцій гранульованого контролю', 'Безкоштовний тариф обмежений', 'Менша спільнота ніж у Midjourney']
WHERE slug = 'krea-ai' AND lang = 'ua';
